<div class="page-title"><div><em>HELP CENTER</em><h1>How can we help?</h1><p>Find answers or connect with our support team.</p></div><button class="btn" data-modal="ticket-modal">Start a conversation</button></div><div class="support-search">⌕ <input placeholder="Search for help with payments, cards, accounts..."></div><div class="help-grid"><article><i>▤</i><h3>Cards</h3><p>Freeze a card, report it lost, or manage limits.</p></article><article><i>↗</i><h3>Payments</h3><p>Transfer status, recipients and payment help.</p></article><article><i>✓</i><h3>Security</h3><p>Password, verification and account safety.</p></article><article><i>▥</i><h3>Accounts</h3><p>Statements, details and account access.</p></article></div><h2 class="section-title">Your requests</h2><section class="panel list"><?php foreach($tickets as $t):?><div class="list-row"><span class="avatar">?</span><div><b><?=html_escape($t['subject'])?></b><small><?=$t['reference']?> · <?=date('M j, g:i a',strtotime($t['updated_at']))?></small></div><span class="<?=status_class($t['status'])?>"><?=ucwords(str_replace('_',' ',$t['status']))?></span></div><?php endforeach?></section><dialog id="ticket-modal"><div class="dialog-head"><h2>Contact support</h2><button data-close>×</button></div><?=form_open('support/create')?><label>Category</label><select name="category"><option>General</option><option>Cards</option><option>Transfers</option><option>Security</option></select><label>Subject</label><input name="subject" required><label>Message</label><textarea name="message" required rows="6"></textarea><button class="btn wide">Submit request</button></form></dialog>
